from pathlib import Path
from collections import Counter
import sqlite3, json, os, re, subprocess, datetime
root=Path('/opt/telegram-robot-leads')
vault=Path('/root/project-secrets/telegram-robot-leads')
state=Path('/var/lib/telegram-robot-leads')
assert root.is_dir() and vault.is_dir() and state.is_dir()
print('READONLY_HISTORICAL_AUDIT_UTC',datetime.datetime.now(datetime.timezone.utc).isoformat(timespec='seconds'))
print('SOURCE_SHA',(root/'.verified-source-commit').read_text().strip())
paths=[]
for base in (root,root/'data',root/'database',root/'db',root/'backups',vault,state):
 if not base.is_dir() or base.is_symlink():continue
 for suffix in ('*.db','*.sqlite','*.sqlite3','*.jsonl'):
  for p in sorted(base.glob(suffix)):
   if p.is_file() and not p.is_symlink() and p.stat().st_size<100000000:
    paths.append(p)
print('CANDIDATE_DATA_FILES',[(str(p),p.stat().st_size) for p in paths])
raw=None
if (vault/'accounts.json').is_file() and not (vault/'accounts.json').is_symlink():
 try: raw=json.loads((vault/'accounts.json').read_text())
 except (ValueError,OSError):pass
session_map={}
if isinstance(raw,list):
 for i,acc in enumerate(raw,1):
  if isinstance(acc,dict) and isinstance(acc.get('session'),str):
   session_map[acc['session']]=f'account_{i}'
def norm_session(x):
 if x is None:return 'UNATTRIBUTED'
 s=str(x)
 if s in session_map:return session_map[s]
 for name,label in session_map.items():
  if s.endswith(name) or name.endswith(s):return label
 return 'UNATTRIBUTED'
def dbreport(path):
 print('SQLITE_FILE',str(path))
 try:
  con=sqlite3.connect('file:'+str(path)+'?mode=ro&immutable=1',uri=True,timeout=2)
  con.execute('PRAGMA query_only=ON')
  tables=[x[0] for x in con.execute("SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%'").fetchall()]
  print('TABLES',tables[:25])
  for t in tables[:30]:
   if not re.fullmatch(r'[A-Za-z_][A-Za-z0-9_]{0,99}',t):continue
   cols=[c[1] for c in con.execute('PRAGMA table_info("'+t+'")')]
   print('SCHEMA',t,cols[:35])
   if t in ('users','adder_daily','events','adder_events','operation_events','invite_events','invites','add_history','metrics','invite_history'):
    if t=='users' and 'status' in cols:
     res=con.execute("SELECT status,COUNT(*) FROM users GROUP BY status ORDER BY COUNT(*) DESC").fetchall()
     print('USERS_STATUS_COUNTS',[(str(k)[:55],v) for k,v in res][:30])
     if 'account_name' in cols:
      r=con.execute("SELECT account_name,status,COUNT(*) FROM users WHERE lower(status) in ('added','success','invite_ok') GROUP BY account_name,status").fetchall()
      print('USERS_ADDED_BY_ACCOUNT',[(norm_session(a),str(st),cnt) for a,st,cnt in r])
    if t=='adder_daily' and {'day','session','adds_ok'}.issubset(cols):
     rs=con.execute("SELECT session,SUM(adds_ok),COUNT(*),MIN(day),MAX(day) FROM adder_daily GROUP BY session").fetchall()
     print('ADDER_DAILY_SUMMARY',[(norm_session(a),int(total or 0),days,first,last) for a,total,days,first,last in rs])
     print('ADDER_DAILY_TOTAL',con.execute("SELECT COALESCE(SUM(adds_ok),0) FROM adder_daily").fetchone()[0])
    if {'event_type','session'}.issubset(cols):
     rs=con.execute('SELECT session,event_type,COUNT(*) FROM "'+t+'" GROUP BY session,event_type ORDER BY COUNT(*) DESC LIMIT 45').fetchall()
     print('EVENT_TYPE_BY_ACCOUNT',[(norm_session(a),str(ev)[:80],n) for a,ev,n in rs])
    elif 'event_type' in cols:
     rs=con.execute('SELECT event_type,COUNT(*) FROM "'+t+'" GROUP BY event_type ORDER BY COUNT(*) DESC LIMIT 30').fetchall()
     print('EVENT_TYPES',[(str(ev)[:80],n) for ev,n in rs])
  con.close()
 except (sqlite3.Error, OSError, ValueError) as e:
  print('SQLITE_INSPECT_UNAVAILABLE',type(e).__name__)
for p in paths:
 if p.suffix.lower() in ('.db','.sqlite','.sqlite3'):
  dbreport(p)
 if p.suffix.lower()=='.jsonl':
  counts=Counter();acct=Counter();total=0;invalid=0
  try:
   with p.open('rb') as h:
    for line in h:
     total+=1
     if total>500000:break
     try: event=json.loads(line)
     except ValueError:invalid+=1;continue
     if not isinstance(event,dict):continue
     kind=str(event.get('event_type',event.get('type',event.get('kind','unknown'))))
     counts[kind]+=1
     if kind.casefold() in ('invite_ok','member_added','add_ok','member_add_success','added'):
      acct[norm_session(event.get('session',event.get('account')))]+=1
   print('JSONL_AGGREGATE',str(p),'LINES',total,'TYPES',counts.most_common(24),'SUCCESS_BY_ACCOUNT',dict(acct),'INVALID',invalid)
  except (OSError,ValueError) as e:print('JSONL_INSPECT_UNAVAILABLE',type(e).__name__)
# Operational state is current only; keep distinct from historical records.
for p in (state/'operation-state.json',vault/'estado_bot.json',root/'estado_bot.json'):
 if not p.is_file() or p.is_symlink():continue
 try:
  data=json.loads(p.read_text())
  if p.name=='operation-state.json':
   print('CURRENT_APPROVED_USER_DONE',len(data.get('approved_users_done',{})))
   print('CURRENT_APPROVED_USER_IDS_DONE',len(data.get('approved_user_ids_done',{})))
   print('CURRENT_ACCOUNTS_MEMBER_ADDS',[(i,data.get('accounts',{}).get(i,{}).get('member_adds')) for i in ('1','2')])
  elif isinstance(data,dict):
   counts=Counter(str(v.get('status') if isinstance(v,dict) else v) for v in data.values())
   print('LEGACY_STATE_STATUS_AGGREGATE',str(p),counts.most_common(16))
 except (OSError,ValueError) as e:print('STATE_INSPECT_UNAVAILABLE',type(e).__name__)
# Read-only inspect scoped PM2 logs. No raw member identifiers or log lines are exported.
pm=subprocess.run(['pm2','jlist'],env={**os.environ,'PM2_HOME':'/root/.pm2'},capture_output=True,text=True,timeout=12)
if pm.returncode==0:
 workers=[x for x in json.loads(pm.stdout) if x.get('name')=='telegram-robot-leads']
 if len(workers)==1:
  m=workers[0].get('pm2_env',{})
  for field in ('pm_out_log_path','pm_err_log_path'):
   p=Path(m.get(field,''))
   if not p.is_file() or p.is_symlink():continue
   size=p.stat().st_size
   with p.open('rb') as h:
    h.seek(max(0,size-3000000))
    txt=h.read().decode('utf-8','replace')
   cases=Counter()
   for line in txt.splitlines():
    if 'Sucesso! Adicionados hoje:' in line:cases['legacy_add_success_logged']+=1
    if 'invite_ok' in line:cases['invite_ok_logged']+=1
    if '\"members_added\":' in line:cases['new_worker_cycle']+=1
   print('PM2_LOG_AGGREGATE',field,'file_bytes',size,'trailing_bytes',min(size,3000000),'counters',dict(cases))
print('AUDIT_READONLY_COMPLETE')
